function groupSizes(n,p){const a=[];while(n>0){if(n<=p){if(n===1&&a.length){if(a[a.length-1]>2){a[a.length-1]--;a.push(2);}else a[a.length-1]++;}else a.push(n);break;}a.push(p);n-=p;}return a;}
