function plan(s){if(s.blueprints)return s.blueprints.map((b,i)=>makeItem(b,i,b.code,b.kind==='Grup'?b.groupCode:b.code));const ids=[];if(s.kind==='Grup')groupSizes(s.count,s.perGroup).forEach((n,i)=>{for(let j=0;j<n;j++)ids.push('BAHAN-'+String(i+1).padStart(2,'0'));});else for(let i=0;i<s.count;i++)ids.push('BAHAN-'+String(i+1).padStart(2,'0'));return ids.map((g,i)=>makeItem(s,i,'SOAL-'+String(i+1).padStart(2,'0'),g));}
