 for(let i=0;i<t.length;i++){const c=t[i];if(c==='"'&&atStart){quoted=true;atStart=false;}else if(c==='"'&&quoted){if(t[i+1]==='"'){field+='"';i++;}else quoted=false;}else if((c==='\n'||c==='\t')&&!quoted){if(field.trim())cells.push(field.trim());field='';atStart=true;}else{field+=c;atStart=false;}}
