$('login-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;if(!$('login-form').reportValidity())return;busy=true;const btn=$('login-form').querySelector('[type=submit]');btn.disabled=true;msg('login-error','');try{const hash=await hashText($('pass').value);if($('user').value.trim()!=='edumind'||hash!==HASH)throw Error('Username atau password belum sesuai. Silakan coba lagi.');try{sessionStorage.setItem(SESSION,JSON.stringify({v:VERSION,until:Date.now()+12*60*60*1000}));}catch(_){}$('pass').value='';showApp();}catch(err){msg('login-error',err.message,'error');$('pass').value='';$('pass').focus();}finally{busy=false;btn.disabled=false;}});
