$('help').addEventListener('click',()=>{$('guide').open=!$('guide').open;$('guide').scrollIntoView({behavior:'smooth',block:'center'});});
function options(el,items,value,placeholder){el.replaceChildren();if(placeholder){const o=new Option(placeholder,'');el.add(o);}let prev='',parent=el;items.forEach(x=>{const obj=typeof x==='string'?{id:x,name:x}:x;if(obj.group&&obj.group!==prev){parent=document.createElement('optgroup');parent.label=obj.group;el.append(parent);prev=obj.group;}else if(!obj.group)parent=el;const o=new Option(obj.name,obj.id);parent.append(o);});el.value=value;}
function scope(){const t=topics(state).find(x=>x.id===state.topic);const src=sourceFor(state);$('route').textContent=extra(state)?'Latihan tambahan SMP/MTs • Mengacu CP Fase D, bukan mata uji TKA resmi.':'Model soal latihan TKA • Acuan: Perka BSKAP 047/H/AN/2025.';$('route').className='notice'+(extra(state)?' amber':'');$('scope').textContent=t?(state.subject==='Bahasa Indonesia'?(state.grade==='SD/MI'?'Bacaan 150–200 kata. ':'Bacaan 200–250 kata. ')+DATA.readingRules[state.grade][state.topic]:state.subject==='Bahasa Inggris'?'Fokus membaca Fase D. Jenis dan panjang teks merupakan pilihan latihan Edumind.':(t.limit||t.name)):'Pilih materi agar batasan acuannya tampil di sini.';if(t?.visual)$('scope').textContent+=' Gambar yang akurat diperlukan untuk mengukur kemampuan ini.';
 const n=state.blueprints?state.blueprints.length:state.count;if(Number.isInteger(n)&&n>0&&n<=10){if(state.blueprints)$('distribution').textContent=n+' soal mengikuti rencana Blueprint. Lepaskan Blueprint untuk mengubah pilihan utama.';else{const forms=state.form==='CAMPURAN'?Array.from({length:n},(_,i)=>['PG','MCMA','KATEGORI'][i%3]):Array(n).fill(state.form);const c={};forms.forEach(x=>c[x]=(c[x]||0)+1);$('distribution').textContent=Object.entries(c).map(([k,v])=>v+' '+FORMS[k]).join(' • ')+(state.kind==='Grup'&&n>1?' | Pembagian bahan: '+groupSizes(n,state.perGroup).join(' + ')+' soal.':'');}}else $('distribution').textContent='Gunakan 1–10 soal per pembuatan.';}
function render(all=false){options($('grade'),Object.keys(SUBJECTS),state.grade);options($('subject'),SUBJECTS[state.grade],state.subject);options($('topic'),topics(state),state.topic,state.subject==='Matematika'||state.subject==='IPA'?'Pilih materi…':'Pilih jenis bacaan…');options($('focus'),['Otomatis',...focusOptions(state)],state.focus);$('topic-label').textContent=['Bahasa Indonesia','Bahasa Inggris'].includes(state.subject)?'Jenis bacaan':'Materi';$('focus-label').textContent=state.subject==='Matematika'?'Tingkat berpikir':'Kemampuan yang dilatih';$('goal-wrap').hidden=state.subject!=='Bahasa Indonesia';options($('goal'),[{id:'Otomatis',name:'Otomatis — variasi sesuai pilihan'},...goals(state)],state.goal);options($('math-skill'),['Otomatis',...(DATA.mathSkills[state.grade]||[])],state.mathSkill);$('math-wrap').hidden=state.subject!=='Matematika';$('visual-wrap').hidden=['Bahasa Indonesia','Bahasa Inggris'].includes(state.subject);options($('form-type'),Object.entries(FORMS).map(([id,name])=>({id,name})),state.form);$('count').value=state.blueprints?state.blueprints.length:state.count;$('kind').value=state.kind;$('per-group').value=state.perGroup;$('per-wrap').hidden=state.kind!=='Grup';
 for(const [id,k,opts]of [['difficulty','difficulty',DIFFICULTIES],['context','context',CONTEXTS],['visual','visual',VISUALS],['category','category',CATEGORIES],['output-format','outputFormat',FORMATS]])options($(id),opts,state[k]);
 for(const k of ['purpose','material','notes'])$(k).value=state[k];
 const locked=!!state.blueprints;for(const id of ['grade','subject','topic','focus','goal','math-skill','form-type','count','kind','per-group','purpose','material'])$(id).disabled=locked;$('detach').hidden=!locked;
 if(all)msg('error','');scope();}
const fieldMap={'grade':'grade','subject':'subject','topic':'topic','focus':'focus','goal':'goal','math-skill':'mathSkill','form-type':'form','count':'count','kind':'kind','per-group':'perGroup','difficulty':'difficulty','context':'context','visual':'visual','category':'category','output-format':'outputFormat','purpose':'purpose','material':'material','notes':'notes'};
Object.entries(fieldMap).forEach(([id,k])=>{const el=$(id);el.addEventListener(el.tagName==='TEXTAREA'||id==='count'?'input':'change',()=>{state[k]=['count','perGroup'].includes(k)?Number(el.value):el.value;
 if(id==='grade'){state.subject='Matematika';state.topic='';state.focus='Otomatis';state.goal='Otomatis';state.mathSkill='Otomatis';state.purpose='';state.material='';state.notes='';state.visual='Otomatis';render();}
 else if(id==='subject'){state.topic='';state.focus='Otomatis';state.goal='Otomatis';state.mathSkill='Otomatis';state.purpose='';state.material='';state.notes='';state.visual='Otomatis';render();}
 else if(id==='topic'||id==='focus'){state.goal='Otomatis';state.purpose='';state.material='';render();}
 else if(id==='kind'){$('per-wrap').hidden=state.kind!=='Grup';}
 clearOutput('Pilihan berubah. Klik Buat Prompt untuk memperbarui hasil.');msg('error','');scope();});});
$('form').addEventListener('submit',e=>{e.preventDefault();if(!signed)return;try{const result=buildPrompt(state);$('output').value=result.text;$('output').scrollTop=0;$('copy').disabled=false;$('download').disabled=false;$('output-meta').textContent=result.items.length+' soal • '+state.grade+' • '+state.subject+' • '+(extra(state)?'Latihan tambahan':'Model soal TKA');msg('error','');msg('status','Prompt siap. Salin ke layanan AI, lalu periksa hasilnya.','notice');$('output').focus();}catch(err){clearOutput();msg('error',err.message,'error');$('error').scrollIntoView({behavior:'smooth',block:'center'});}});
$('copy').addEventListener('click',async()=>{const text=$('output').value;if(!text)return;try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else throw Error();msg('status','Prompt berhasil disalin. Tempel di layanan AI Anda.','notice');}catch(_){$('output').focus();$('output').select();let ok=false;try{ok=document.execCommand('copy');}catch(_){}msg('status',ok?'Prompt berhasil disalin.':'Prompt sudah dipilih. Tekan Ctrl+C (atau Salin pada HP).','notice');}});
$('download').addEventListener('click',()=>{if(!$('output').value)return;const blob=new Blob(['\ufeff'+$('output').value],{type:'text/plain;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='EDUMIND_PROMPT_'+state.grade.replace(/\W/g,'')+'_'+state.subject.replace(/\s+/g,'_')+'.txt';root.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);});
$('reset').addEventListener('click',()=>{if(!confirm('Kosongkan pilihan dan prompt yang sudah dibuat?'))return;state=DEFAULT();render(true);clearOutput();$('import-text').value='';msg('import-message','');$('topic').focus();});
$('example').addEventListener('click',()=>{const grade=state.grade,subject=state.subject;state={...DEFAULT(),grade,subject};if(subject==='Matematika'){state.topic=grade==='SD/MI'?'AC-005':'AC-056';state.focus=grade==='SD/MI'?'Aplikasi':'Penalaran';state.form=grade==='SD/MI'?'PG':'KATEGORI';state.count=3;state.material=grade==='SD/MI'?'Pembagian sisa persediaan minuman ke beberapa wadah.':'Dua kelompok data dengan rata-rata sama tetapi sebaran berbeda.';}
 else if(subject==='Bahasa Indonesia'){state.topic=grade==='SD/MI'?'Teks fiksi':'Teks informasi';state.focus=grade==='SD/MI'?'Pemahaman Inferensial':'Evaluasi dan Apresiasi';state.form=grade==='SD/MI'?'CAMPURAN':'MCMA';state.count=3;state.kind='Grup';state.material=grade==='SD/MI'?'Cerita tentang kegiatan merapikan perpustakaan sekolah.':'Pengamatan simulasi di sekolah; klaim yang perlu diperiksa berdasarkan data.';}
 else if(subject==='IPA'){state.topic='IPA-10';state.focus=DATA.ipaFocus[1];state.form='MCMA';state.count=3;state.material='Tabel simulasi pendinginan air pada dua wadah. Kondisi pembanding dibuat sama. Kegiatan air panas ditangani guru.';}
 else{state.topic=DATA.engTypes[1];state.focus=DATA.engFocus[1];state.form='PG';state.count=3;state.kind='Grup';state.material='Pengalaman membantu persiapan kegiatan sekolah.';}
 render(true);clearOutput();$('import-text').value='';msg('import-message','');msg('status','Contoh terisi. Anda boleh mengubahnya, lalu klik Buat Prompt.','notice');});
$('import').addEventListener('click',()=>{try{const parsed=parseBlueprint($('import-text').value);state=parsed;render(true);clearOutput();msg('import-message',state.blueprints.length+' rencana berhasil dibaca. Formulir menampilkan pilihan baris pertama; prompt mengikuti SEMUA rencana di bawah.\n'+state.blueprints.map(b=>b.code+' • '+FORMS[b.form]+' • '+topics(b).find(t=>t.id===b.topic).name+' • '+(b.kind==='Grup'?b.groupCode:'Tunggal')).join('\n'),'notice');}catch(err){msg('import-message',err.message,'error');}});
